SELECT b.NUM, 'T' AS SENSING, IFNULL(a.AVR_VAL, -99999) AS TEMP, 
	IFNULL(a.MAX_VAL, -99999) AS TEMP_MAX, IFNULL(a.MIN_VAL, -99999) AS TEMP_MIN
	FROM ( SELECT AVR_VAL, MAX_VAL, MIN_VAL, DATE_FORMAT(TEMP_DATE,  #{format}) AS NUM
		FROM TEMP_HIST
		WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
		AND TEMP_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


SELECT b.NUM, 'A' AS SENSING, IFNULL(a.AVR_VAL, -99999) AS ATMO,
	IFNULL(a.MAX_VAL, -99999) AS ATMO_MAX, IFNULL(a.MIN_VAL, -99999) AS ATMO_MIN
	FROM ( SELECT AVR_VAL, MAX_VAL, MIN_VAL, DATE_FORMAT(ATMO_DATE,  #{format}) AS NUM
		FROM ATMO_HIST
		WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
		AND ATMO_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


SELECT b.NUM, 'H' AS SENSING, IFNULL(a.AVR_VAL, -99999) AS HUMI,
	IFNULL(a.MAX_VAL, -99999) AS HUMI_MAX, IFNULL(a.MIN_VAL, -99999) AS HUMI_MIN
	FROM ( SELECT AVR_VAL, MAX_VAL, MIN_VAL, DATE_FORMAT(HUMI_DATE,  #{format}) AS NUM
		FROM HUMI_HIST
		WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
		AND HUMI_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


SELECT b.NUM, 'W' AS SENSING, IFNULL(a.AVR_VEL1, -99999) AS VEL, IFNULL(a.MAX_VEL, -99999) AS VEL_MAX, 
	IFNULL(a.AVR_DEG1, -99999) AS DEG, IFNULL(a.MAX_DEG, -99999) AS DEG_MAX
	FROM ( SELECT AVR_VEL1, MAX_VEL, AVR_DEG1, MAX_DEG, DATE_FORMAT(WIND_DATE,  #{format}) AS NUM
		FROM WIND_HIST
		WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
		AND WIND_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


SELECT b.NUM, 'D' AS SENSING, IFNULL(a.RADIATION, -99999) AS RADI
		FROM ( SELECT RADIATION, DATE_FORMAT(RADI_DATE,  #{format}) AS NUM
		FROM RADI_HIST
		WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
		AND RADI_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


 SELECT b.NUM, 'S' AS SENSING, IFNULL(a.SUNSHINE, -99999) AS SUNS
